#!/usr/bin/env bash
set -euo pipefail
python3 - "$@" <<'PY'
import csv,sys
from pathlib import Path
src,out=map(Path,sys.argv[1:3])
def amount(n):
    whole,part=divmod(abs(n),100)
    return ('-' if n<0 else '')+str(whole)+'.'+str(part).zfill(2)
with src.open(newline='') as f:rows=list(csv.DictReader(f))
out.parent.mkdir(parents=True,exist_ok=True)
with out.open('w',newline='') as f:
    w=csv.writer(f,lineterminator='\n');w.writerow(['tx_id','account','amount'])
    for r in rows:w.writerow([r['tx_id'],r['account'],amount(int(r['cents']))])
totals={}
for r in rows:
    c,v=totals.get(r['account'],(0,0));totals[r['account']]=(c+1,v+int(r['cents']))
summary=Path(sys.argv[3]);summary.parent.mkdir(parents=True,exist_ok=True)
with summary.open('w',newline='') as f:
    w=csv.writer(f,lineterminator='\n');w.writerow(['account','count','amount'])
    for k,(c,v) in sorted(totals.items()):w.writerow([k,c,amount(v)])
PY
